package com.kuaixietech.cases;
import com.fasterxml.jackson.databind.*;
import com.kuaixietech.security.DomainAccessGuard;
import java.math.BigDecimal;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;
import static com.kuaixietech.cases.CaseModels.*;
@Service
public class TradeCaseService {
 private com.kuaixietech.aftersalesfunds.AftersalesEscrowFunds escrowRefunds;
 @org.springframework.beans.factory.annotation.Autowired public void escrowRefunds(com.kuaixietech.aftersalesfunds.AftersalesEscrowFunds value){this.escrowRefunds=value;}
 private final JdbcTemplate db;private final DomainAccessGuard guard;private final ObjectMapper json;private final Set<String> mediaHosts=new HashSet<>();private final int hours;
 private static final String FIELDS="d.id,d.order_id,d.initiator_id,d.respondent_id,d.type,d.expect_resolution,d.description,d.evidence_urls,d.respondent_evidence_urls,d.respondent_note,d.stage,d.round,d.verdict,d.refund_amount,d.deposit_owner,d.verdict_reason,d.reviewed_by,d.reopened_used,d.review_appeal,d.review_result,d.negotiation_deadline,d.resolved_at,d.created_at";
 public TradeCaseService(JdbcTemplate db,DomainAccessGuard guard,ObjectMapper json,@Value("${kuaixie.portal.allowed-media-hosts:}") String hosts,@Value("${app.disputes.negotiation-hours:48}") int hours){this.db=db;this.guard=guard;this.json=json;if(hours<1||hours>168)throw new IllegalArgumentException("invalid dispute window");this.hours=hours;for(String host:hosts.split(","))if(!host.isBlank())mediaHosts.add(host.trim().toLowerCase(Locale.ROOT));}
 private ResponseStatusException fail(HttpStatus status,String code){return new ResponseStatusException(status,code);}
 private Map<String,Object> row(String sql,Object...args){return db.queryForList(sql,args).stream().findFirst().orElse(null);}
 private void changed(int count){if(count!=1)throw new IllegalStateException("DISPUTE_CONCURRENT_CHANGE");}
 private String encode(Object value){try{return json.writeValueAsString(value);}catch(Exception e){throw new IllegalArgumentException("DISPUTE_INVALID_PAYLOAD");}}
 private String key(String value){try{return UUID.fromString(value).toString();}catch(Exception e){throw fail(HttpStatus.BAD_REQUEST,"DISPUTE_REQUEST_ID_REQUIRED");}}
 private String hash(Object value){try{var node=json.valueToTree(value);if(node.hasNonNull("refundAmount"))((com.fasterxml.jackson.databind.node.ObjectNode)node).put("refundAmount",new BigDecimal(node.get("refundAmount").asText()).stripTrailingZeros().toPlainString());return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json.writeValueAsBytes(node)));}catch(Exception e){throw new IllegalStateException("DISPUTE_PAYLOAD_HASH_FAILED");}}
 private List<String> evidence(List<String> urls){for(String value:urls)try{URI u=URI.create(value);if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getFragment()!=null||u.getPort()!=-1&&u.getPort()!=443||!mediaHosts.contains(u.getHost().toLowerCase(Locale.ROOT)))throw new IllegalArgumentException();}catch(Exception e){throw fail(HttpStatus.BAD_REQUEST,"DISPUTE_EVIDENCE_HOST_REJECTED");}return List.copyOf(new LinkedHashSet<>(urls));}
 private boolean party(Map<String,Object> entry,String actor){return actor.equals(entry.get("initiator_id"))||actor.equals(entry.get("respondent_id"));}
 private void page(int limit,int offset){if(limit<1||limit>100||offset<0)throw fail(HttpStatus.BAD_REQUEST,"DISPUTE_INVALID_PAGE");}
 public List<Map<String,Object>> mine(int limit,int offset){String user=guard.requireActiveProfile();page(limit,offset);return db.queryForList("SELECT d.id,d.order_id,d.type,d.stage,d.expect_resolution,d.description,d.refund_amount,d.round,d.created_at,o.item_name,o.order_no FROM t_disputes d JOIN t_orders o ON o.id=d.order_id WHERE d.initiator_id=? OR d.respondent_id=? ORDER BY d.created_at DESC,d.id DESC LIMIT ? OFFSET ?",user,user,limit,offset);}
 public List<Map<String,Object>> queue(int limit,int offset){guard.requireAdmin();page(limit,offset);return db.queryForList("SELECT d.id,d.order_id,d.type,d.stage,d.expect_resolution,d.refund_amount,d.round,d.created_at,o.item_name,o.order_no,a.refund_status FROM t_disputes d JOIN t_orders o ON o.id=d.order_id LEFT JOIN t_after_sales_cases a ON a.id=d.id ORDER BY CASE WHEN d.stage IN('negotiating','platform_review','appeal','awaiting_refund','awaiting_fulfilment') THEN 0 ELSE 1 END,d.created_at,d.id LIMIT ? OFFSET ?",limit,offset);}
 public Map<String,Object> detail(String id,boolean admin){String actor=admin?guard.requireAdmin():guard.requireActiveProfile();var d=row("SELECT "+FIELDS+",o.item_name,o.order_no,o.goods_amount FROM t_disputes d JOIN t_orders o ON o.id=d.order_id WHERE d.id=?",id);if(d==null||!admin&&!party(d,actor))throw fail(HttpStatus.NOT_FOUND,"DISPUTE_UNAVAILABLE");return projection(d,actor,admin);}
 private Map<String,Object> projection(Map<String,Object> d,String actor,boolean admin){var result=new LinkedHashMap<String,Object>(d);if(!admin)result.remove("reviewed_by");result.put("events",events(d.get("id").toString(),100,0));var after=row("SELECT refund_status,status AS after_sales_status FROM t_after_sales_cases WHERE id=? AND order_id=?",d.get("id"),d.get("order_id"));if(after!=null)result.putAll(after);if(escrowRefunds!=null){var posted=escrowRefunds.forCase(d.get("id").toString());if(posted!=null){result.put("refund_method","escrow_wallet");result.put("escrowRefund",posted);}}result.put("myRole",admin?"operator":actor.equals(d.get("initiator_id"))?"buyer":"merchant");for(String field:List.of("evidence_urls","respondent_evidence_urls"))if(result.get(field) instanceof String s)try{result.put(field,json.readTree(s));}catch(Exception e){throw new IllegalStateException("DISPUTE_INVALID_STORED_EVIDENCE");}return result;}
 private List<Map<String,Object>> events(String id,int limit,int offset){var rows=db.queryForList("SELECT id,actor_role,action,before_stage,after_stage,JSON_REMOVE(payload,'$.requestHash') AS payload,created_at FROM t_dispute_events WHERE dispute_id=? ORDER BY created_at DESC,id DESC LIMIT ? OFFSET ?",id,limit,offset);for(var r:rows)if(r.get("payload") instanceof String s)try{r.put("payload",json.readTree(s));}catch(Exception e){throw new IllegalStateException("DISPUTE_INVALID_EVENT");}return rows;}
 public List<Map<String,Object>> history(String id,int limit,int offset,boolean admin){String user=admin?guard.requireAdmin():guard.requireActiveProfile();page(limit,offset);var d=row("SELECT id,initiator_id,respondent_id FROM t_disputes WHERE id=?",id);if(d==null||!admin&&!party(d,user))throw fail(HttpStatus.NOT_FOUND,"DISPUTE_UNAVAILABLE");return events(id,limit,offset);}
 @Transactional public Map<String,String> create(Create input){String actor=guard.requireActiveProfile(),request=key(input.requestId());var order=row("SELECT id,buyer_id,vendor_id,status,goods_amount FROM t_orders WHERE id=? FOR UPDATE",input.orderId());if(order==null||!actor.equals(order.get("buyer_id")))throw fail(HttpStatus.NOT_FOUND,"DISPUTE_ORDER_UNAVAILABLE");String id=UUID.nameUUIDFromBytes(("dispute:"+actor+":"+request).getBytes(StandardCharsets.UTF_8)).toString();var prior=row("SELECT * FROM t_disputes WHERE id=? FOR UPDATE",id);if(prior!=null){if(replayed(id,actor,request,"created",input))return Map.of("id",id,"stage",prior.get("stage").toString());throw fail(HttpStatus.CONFLICT,"DISPUTE_REQUEST_REUSED");}
  if(!Set.of("purchased","shipped","delivered","completed").contains(order.get("status"))||order.get("vendor_id")==null||actor.equals(order.get("vendor_id")))throw fail(HttpStatus.CONFLICT,"DISPUTE_ORDER_NOT_ELIGIBLE");
  if(!db.queryForList("SELECT id FROM t_disputes WHERE order_id=? AND stage NOT IN('resolved','closed') FOR UPDATE",input.orderId()).isEmpty())throw fail(HttpStatus.CONFLICT,"DISPUTE_ALREADY_OPEN");
  BigDecimal amount=amount(input.expectResolution(),input.refundAmount(),new BigDecimal(order.get("goods_amount").toString()));var urls=evidence(input.evidenceUrls());
  changed(db.update("INSERT INTO t_disputes(id,order_id,initiator_id,respondent_id,type,expect_resolution,description,evidence_urls,respondent_evidence_urls,stage,round,refund_amount,negotiation_deadline) VALUES(?,?,?,?,?,?,?,?,JSON_ARRAY(),'negotiating',1,?,TIMESTAMPADD(HOUR,?,CURRENT_TIMESTAMP(3)))",id,input.orderId(),actor,order.get("vendor_id"),input.type(),input.expectResolution(),input.description().trim(),encode(urls),amount,hours));
  event(id,input.orderId(),actor,"buyer","created",request,null,"negotiating",input);notice(order.get("vendor_id").toString(),input.orderId(),"买家发起商品交易纠纷，请查看并回应");return Map.of("id",id,"stage","negotiating");
 }
 private BigDecimal amount(String outcome,BigDecimal requested,BigDecimal goods){if(Set.of("reject","resend").contains(outcome)){if(requested!=null)throw fail(HttpStatus.BAD_REQUEST,"DISPUTE_AMOUNT_INVALID");return null;}if("refund_full".equals(outcome)){if(requested!=null&&requested.compareTo(goods)!=0)throw fail(HttpStatus.BAD_REQUEST,"DISPUTE_AMOUNT_INVALID");return goods;}if(requested==null||requested.signum()<=0||requested.scale()>2||requested.compareTo(goods)>0)throw fail(HttpStatus.BAD_REQUEST,"DISPUTE_AMOUNT_INVALID");return requested;}
 private record Locked(Map<String,Object> dispute,Map<String,Object> order){}
 private Locked lock(String id,String actor,boolean admin){var initial=row("SELECT order_id FROM t_disputes WHERE id=?",id);if(initial==null)throw fail(HttpStatus.NOT_FOUND,"DISPUTE_UNAVAILABLE");var order=row("SELECT id,buyer_id,vendor_id,status,goods_amount FROM t_orders WHERE id=? FOR UPDATE",initial.get("order_id"));var d=row("SELECT *,negotiation_deadline>CURRENT_TIMESTAMP(3) AS negotiation_open FROM t_disputes WHERE id=? FOR UPDATE",id);if(order==null||d==null||!admin&&!party(d,actor))throw fail(HttpStatus.NOT_FOUND,"DISPUTE_UNAVAILABLE");return new Locked(d,order);}
 private void round(Map<String,Object> d,int expected){if(((Number)d.get("round")).intValue()!=expected)throw fail(HttpStatus.CONFLICT,"DISPUTE_CHANGED_REFRESH");}
 private boolean replayed(String id,String actor,String request,String action,Object input){var existing=row("SELECT action,JSON_UNQUOTE(JSON_EXTRACT(payload,'$.requestHash')) AS request_hash FROM t_dispute_events WHERE dispute_id=? AND actor_id=? AND request_id=? FOR UPDATE",id,actor,request);if(existing==null)return false;if(!action.equals(existing.get("action"))||!hash(input).equals(existing.get("request_hash")))throw fail(HttpStatus.CONFLICT,"DISPUTE_REQUEST_REUSED");return true;}
 private void event(String id,String order,String actor,String role,String action,String request,String before,String after,Object input){Map<String,Object> payload=new LinkedHashMap<>();payload.put("requestHash",hash(input));payload.put("input",json.valueToTree(input));changed(db.update("INSERT INTO t_dispute_events(id,dispute_id,order_id,actor_id,actor_role,action,request_id,before_stage,after_stage,payload) VALUES(?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID().toString(),id,order,actor,role,action,request,before,after,encode(payload)));}
 private void notice(String user,String order,String body){changed(db.update("INSERT INTO t_notifications(id,user_id,kind,title,body,order_id) VALUES(?,?,'dispute','交易纠纷进度',?,?)",UUID.randomUUID().toString(),user,body,order));}
 @Transactional public Map<String,String> respond(String id,Respond input){String actor=guard.requireActiveProfile(),request=key(input.requestId());var state=lock(id,actor,false);var d=state.dispute();if(replayed(id,actor,request,"responded",input))return result(d);round(d,input.expectedRound());if(!Set.of("negotiating","platform_review","appeal","awaiting_fulfilment","awaiting_refund").contains(d.get("stage")))throw fail(HttpStatus.CONFLICT,"DISPUTE_STAGE_REJECTED");if("negotiating".equals(d.get("stage"))&&!truth(d.get("negotiation_open")))throw fail(HttpStatus.CONFLICT,"DISPUTE_ESCALATE_REQUIRED");var urls=evidence(input.evidenceUrls());String column=actor.equals(d.get("respondent_id"))?"respondent_evidence_urls":"evidence_urls";String current=String.valueOf(d.get(column));try{if(json.readTree(current).size()+urls.size()>20)throw fail(HttpStatus.BAD_REQUEST,"DISPUTE_TOO_MUCH_EVIDENCE");}catch(com.fasterxml.jackson.core.JsonProcessingException e){throw new IllegalStateException("DISPUTE_INVALID_STORED_EVIDENCE");}
  changed(db.update("UPDATE t_disputes SET "+column+"=JSON_MERGE_PRESERVE("+column+",CAST(? AS JSON)),respondent_note=CASE WHEN respondent_id=? THEN ? ELSE respondent_note END,round=round+1 WHERE id=?",encode(urls),actor,input.note().trim(),id));if(actor.equals(d.get("respondent_id")))db.update("UPDATE t_after_sales_cases SET merchant_response=? WHERE id=?",input.note().trim(),id);event(id,d.get("order_id").toString(),actor,actor.equals(d.get("initiator_id"))?"buyer":"merchant","responded",request,d.get("stage").toString(),d.get("stage").toString(),input);notice(actor.equals(d.get("initiator_id"))?d.get("respondent_id").toString():d.get("initiator_id").toString(),d.get("order_id").toString(),"对方已补充纠纷材料，请查看");return result(d);
 }
 private boolean truth(Object value){return Boolean.TRUE.equals(value)||"1".equals(String.valueOf(value));}
 private Map<String,String> result(Map<String,Object> d){return Map.of("id",d.get("id").toString(),"stage",d.get("stage").toString());}
 @Transactional public Map<String,String> escalate(String id,Escalate input){String actor=guard.requireActiveProfile(),request=key(input.requestId());var d=lock(id,actor,false).dispute();if(replayed(id,actor,request,"escalated",input))return result(d);round(d,input.expectedRound());if(!"negotiating".equals(d.get("stage")))throw fail(HttpStatus.CONFLICT,"DISPUTE_STAGE_REJECTED");changed(db.update("UPDATE t_disputes SET stage='platform_review',round=round+1 WHERE id=?",id));event(id,d.get("order_id").toString(),actor,actor.equals(d.get("initiator_id"))?"buyer":"merchant","escalated",request,"negotiating","platform_review",input);return Map.of("id",id,"stage","platform_review");}
 @Transactional public Map<String,String> decide(String id,Decision input){String actor=guard.requireAdmin(),request=key(input.requestId());var state=lock(id,actor,true);var d=state.dispute();if(replayed(id,actor,request,"decided",input))return result(d);round(d,input.expectedRound());String before=d.get("stage").toString();if(!Set.of("platform_review","appeal").contains(before))throw fail(HttpStatus.CONFLICT,"DISPUTE_STAGE_REJECTED");var prior=row("SELECT refund_status FROM t_after_sales_cases WHERE id=? FOR UPDATE",id);if(prior!=null&&Set.of("succeeded","completed","paid","processing").contains(prior.get("refund_status")))throw fail(HttpStatus.CONFLICT,"DISPUTE_REFUND_RECONCILIATION_REQUIRED");BigDecimal amount=amount(input.outcome(),input.refundAmount(),new BigDecimal(state.order().get("goods_amount").toString()));if(amount!=null){BigDecimal already=BigDecimal.ZERO;for(var r:db.queryForList("SELECT id,refund_amount FROM t_after_sales_cases WHERE order_id=? AND id<>? AND refund_status NOT IN('not_required','cancelled') FOR UPDATE",d.get("order_id"),id))if(r.get("refund_amount")!=null)already=already.add(new BigDecimal(r.get("refund_amount").toString()));if(already.add(amount).compareTo(new BigDecimal(state.order().get("goods_amount").toString()))>0)throw fail(HttpStatus.CONFLICT,"DISPUTE_REFUND_CAP_EXCEEDED");}String after=amount!=null?"awaiting_refund":"resend".equals(input.outcome())?"awaiting_fulfilment":"resolved";
  changed(db.update("UPDATE t_disputes SET stage=?,verdict=?,refund_amount=?,deposit_owner=?,verdict_reason=?,reviewed_by=?,review_result=CASE WHEN ?='appeal' THEN ? ELSE review_result END,resolved_at=CASE WHEN ?='resolved' THEN CURRENT_TIMESTAMP(3) ELSE NULL END,round=round+1 WHERE id=?",after,input.outcome(),amount,input.depositOwner(),input.reason().trim(),actor,before,input.outcome(),after,id));
  if(amount!=null||"resend".equals(input.outcome()))db.update("INSERT INTO t_after_sales_cases(id,order_id,applicant_id,case_type,reason,status,merchant_response,operator_note,refund_status,refund_amount) VALUES(?,?,?,'trade_dispute',?,?,?,?,?,?) ON DUPLICATE KEY UPDATE status=VALUES(status),merchant_response=COALESCE(VALUES(merchant_response),merchant_response),operator_note=VALUES(operator_note),refund_status=VALUES(refund_status),refund_amount=VALUES(refund_amount)",id,d.get("order_id"),d.get("initiator_id"),String.valueOf(d.get("description")).substring(0,Math.min(2000,String.valueOf(d.get("description")).length())),after,d.get("respondent_note"),input.reason().trim(),amount==null?"not_required":"provider_unavailable",amount);
  else if(prior!=null)db.update("UPDATE t_after_sales_cases SET status='closed',refund_status='not_required',refund_amount=NULL,operator_note=? WHERE id=?",input.reason().trim(),id);
  event(id,d.get("order_id").toString(),actor,"operator","decided",request,before,after,input);changed(db.update("INSERT INTO t_admin_logs(id,operator_id,action,target_type,target_id,detail) VALUES(?,?,'dispute_decision','dispute',?,?)",UUID.randomUUID().toString(),actor,id,input.reason().trim()));notice(d.get("initiator_id").toString(),d.get("order_id").toString(),"平台已记录纠纷裁决；退款须以实际资金处理结果为准");notice(d.get("respondent_id").toString(),d.get("order_id").toString(),"平台已记录纠纷裁决，请查看履行要求");return Map.of("id",id,"stage",after);
 }
 @Transactional public Map<String,String> appeal(String id,Appeal input){String actor=guard.requireActiveProfile(),request=key(input.requestId());var d=lock(id,actor,false).dispute();if(replayed(id,actor,request,"appealed",input))return result(d);round(d,input.expectedRound());if(truth(d.get("reopened_used"))||!Set.of("resolved","awaiting_refund","awaiting_fulfilment").contains(d.get("stage")))throw fail(HttpStatus.CONFLICT,"DISPUTE_APPEAL_UNAVAILABLE");if(!db.queryForList("SELECT id FROM t_disputes WHERE order_id=? AND id<>? AND stage NOT IN('resolved','closed') FOR UPDATE",d.get("order_id"),id).isEmpty())throw fail(HttpStatus.CONFLICT,"DISPUTE_ANOTHER_CASE_OPEN");var prior=row("SELECT refund_status FROM t_after_sales_cases WHERE id=? FOR UPDATE",id);if(prior!=null&&Set.of("processing","succeeded","completed","paid").contains(prior.get("refund_status")))throw fail(HttpStatus.CONFLICT,"DISPUTE_REFUND_RECONCILIATION_REQUIRED");changed(db.update("UPDATE t_disputes SET stage='appeal',reopened_used=1,review_appeal=?,resolved_at=NULL,round=round+1 WHERE id=?",input.reason().trim(),id));if(prior!=null)db.update("UPDATE t_after_sales_cases SET status='on_hold',refund_status=CASE WHEN refund_status='not_required' THEN refund_status ELSE 'on_hold' END WHERE id=?",id);event(id,d.get("order_id").toString(),actor,actor.equals(d.get("initiator_id"))?"buyer":"merchant","appealed",request,d.get("stage").toString(),"appeal",input);return Map.of("id",id,"stage","appeal");}
 @Transactional public Map<String,String> finish(String id,Finish input){String actor=guard.requireActiveProfile(),request=key(input.requestId());var d=lock(id,actor,false).dispute();if(!actor.equals(d.get("initiator_id")))throw fail(HttpStatus.FORBIDDEN,"DISPUTE_BUYER_REQUIRED");if(replayed(id,actor,request,"fulfilled",input))return result(d);round(d,input.expectedRound());if(!"awaiting_fulfilment".equals(d.get("stage")))throw fail(HttpStatus.CONFLICT,"DISPUTE_STAGE_REJECTED");changed(db.update("UPDATE t_disputes SET stage='resolved',resolved_at=CURRENT_TIMESTAMP(3),round=round+1 WHERE id=?",id));db.update("UPDATE t_after_sales_cases SET status='resolved' WHERE id=? AND refund_status='not_required'",id);event(id,d.get("order_id").toString(),actor,"buyer","fulfilled",request,"awaiting_fulfilment","resolved",input);return Map.of("id",id,"stage","resolved");}
}
